from pathlib import Path
root=Path(__file__).resolve().parent.parent
s=(root/'sprint-helper.js').read_text()
helpers=s[s.index('function parsePoints('):s.index('// Helper: Check if card title')]+s[s.index('function s4tIsCommonCard('):s.index('function s4tIsCommonCardElement(')]
setup='''function getBoardShortLink(){return 'fixture'};const board={name:'Sprint',members:[{id:'a',fullName:'Alex'},{id:'b',fullName:'Blair'},{id:'c',fullName:'Chris'}],lists:[],cards:[{id:'1',name:'(4) Work',idMembers:['a'],labels:[{id:'h',name:'Hotfix'}]},{id:'2',name:'(2) Other',idMembers:['b'],labels:[]}]};function fetchBoardData(id,force,cb){setTimeout(()=>cb(null,board),5)};let popup, pipCalls=0, fallbackCalls=0;function makePopup(){const frame=document.createElement('iframe');frame.style.cssText='width:420px;height:480px;border:0';document.body.append(frame);popup={document:frame.contentDocument,closed:false,focus(){this.focused=true},addEventListener(){},close(){this.closed=true;frame.remove()}};return popup}Object.defineProperty(window,'documentPictureInPicture',{configurable:true,value:{requestWindow:async()=>{pipCalls++;return makePopup()}}});window.open=()=>{fallbackCalls++;return makePopup()};'''
tests='''(async()=>{const wait=ms=>new Promise(r=>setTimeout(r,ms)),errors=[],check=(v,m)=>{if(!v)errors.push(m)},el=s=>document.querySelector(s);try{s4tOpenCharts();await wait(50);check(document.querySelectorAll('.s4t-chart-slice').length===2,'two developer slices');const slice=el('.s4t-chart-slice');slice.dispatchEvent(new MouseEvent('mouseenter'));check(slice.style.transform.includes('translate'),'hover peeks out');slice.click?.();slice.dispatchEvent(new MouseEvent('click'));check(slice.getAttribute('aria-pressed')==='true','slice selection pinned');el('[data-chart-tab="labels"]').click();check(el('.s4t-chart-note').textContent.includes('Multi-label'),'overlap explained');check(el('.s4t-chart-legend').textContent.includes('Hotfix'),'label names shown');el('[data-chart-popout]').click();await wait(30);check(pipCalls===1 && fallbackCalls===0,'prefers floating PiP');check(popup.document.querySelector('[data-chart-tab="labels"]').getAttribute('aria-selected')==='true','popout retains selected tab');check(popup.document.querySelectorAll('.s4t-chart-slice').length===2,'popout rendered chart');el('[data-chart-close]').click();check(!el('.s4t-chart-overlay'),'popup closes');check(!popup.closed,'closing source preserves peek');const detached=popup.document.querySelector('.s4t-chart-dialog');check(detached.classList.contains('s4t-chart-detached'),'detached layout');check(!detached.querySelector('.s4t-chart-note') && !detached.querySelector('.s4t-chart-legend'),'peek has no footer or legend');const paths=detached.querySelectorAll('.s4t-chart-slice');paths[0].focus();paths[0].dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',bubbles:true}));check(popup.document.activeElement===paths[1],'right arrow moves to next slice');paths[1].dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowDown',bubbles:true}));check(popup.document.activeElement===paths[0],'down arrow wraps');paths[0].dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowLeft',bubbles:true}));check(popup.document.activeElement===paths[1],'left arrow wraps');paths[1].dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}));check(paths[1].getAttribute('aria-pressed')==='true','keyboard pins slice');check(detached.querySelectorAll('.s4t-chart-percentage').length===2,'readable percentages');check(detached.querySelector('.s4t-chart-canvas').getBoundingClientRect().height>350,'peek chart uses available height');check(Math.abs(detached.getBoundingClientRect().width-420)<2,'fills window width');check(Math.abs(detached.getBoundingClientRect().height-480)<2,'fills window height');popup.document.querySelector('[data-chart-tab="dev"]').click();check(popup.document.querySelector('[data-chart-tab="dev"]').getAttribute('aria-selected')==='true','peek interactive after source closes');popup.document.querySelector('[data-chart-refresh]').click();await wait(30);check(popup.document.querySelectorAll('.s4t-chart-slice').length===2,'peek refresh independent');s4tOpenCharts();await wait(30);el('[data-chart-popout]').click();check(pipCalls===1 && popup.focused,'existing peek reused');popup.document.querySelector('[data-chart-close]').click();check(popup.closed && el('.s4t-chart-overlay'),'peek close preserves source');window.documentPictureInPicture.requestWindow=async()=>{throw Error('Unavailable')};el('[data-chart-popout]').click();await wait(30);check(fallbackCalls===1,'small popup fallback');el('[data-chart-close]').click();check(!popup.closed,'fallback survives source close');popup.document.querySelector('[data-chart-close]').click();}catch(e){errors.push(e.stack)}el('#result').textContent=errors.length?'FAIL: '+errors.join('; '):'PASS: pie slices, hover, selection, tabs, popout and close';})();'''
Path('/tmp/s4t-charts-ui.html').write_text('<html><body><pre id="result">RUNNING</pre><script>'+setup+helpers+(root/'charts.js').read_text()+tests+'</script></body></html>')
